var sb = new System.Text.StringBuilder();
foreach(var go in UnityEngine.Object.FindObjectsByType<UnityEngine.GameObject>(UnityEngine.FindObjectsInactive.Include, UnityEngine.FindObjectsSortMode.None))
{
    if (go.name.Contains("Lab") || go.name.Contains("Floor") || go.name.Contains("Wall"))
    {
        sb.AppendLine($"Lab obj: {go.name}, pos={go.transform.position}, rot={go.transform.rotation.eulerAngles}, scale={go.transform.lossyScale}");
        var mr = go.GetComponent<UnityEngine.MeshRenderer>();
        if (mr != null)
        {
            sb.AppendLine($"  MR: boundsCenter={mr.bounds.center}, boundsExtents={mr.bounds.extents}");
        }
    }
}
System.IO.File.WriteAllText("c:/projects/LAST-GOD/scratch/lab_diag.txt", sb.ToString());
